result = ee_move('left', pose_now, 1.0, 3, min_steps=3)
if not result[2] and not result[3]:
    result = ee_move('left', [-0.300, -0.32, 0.90] + qupright, 1.0, 3)
if not result[2] and not result[3]:
    for i in range(9):
        result = step(home)
        if result[2] or result[3]:
            break
print({'reward': result[1], 'terminated': result[2], 'truncated': result[3], 'info': result[4]})

